// WF-21: public registration. Body: { full_name, email, phone?, whatsapp?, department?, position? }
const b = $json.body || $json;
const name = String(b.full_name || '').trim();
const email = String(b.email || '').toLowerCase().trim();
const phone = b.phone || null;
const wa = b.whatsapp || null;
const dept = b.department || null;
const pos = b.position || null;
const emailRe = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
let err = null;
if (!name) err = 'full_name is required';
else if (!emailRe.test(email)) err = 'a valid email is required';

let sql, params;
if (err) { sql = `SELECT 'ERR' AS err`; params = []; }
else {
  sql = `WITH ins AS (
  INSERT INTO users (full_name, email, phone, whatsapp, department, position, role, status)
  VALUES ($1,$2,$3,$4,$5,$6,'EMPLOYEE','PENDING')
  ON CONFLICT (email) DO NOTHING
  RETURNING user_id, email, status
),
aud AS (
  INSERT INTO audit_logs (actor_id, action, record_id, metadata)
  SELECT user_id, 'USER_REGISTERED', user_id, json_build_object('email', email) FROM ins RETURNING 1
),
notif AS (
  INSERT INTO notifications (user_id, type, message)
  SELECT adm.user_id, 'NEW_REGISTRATION', 'New registration pending approval: ' || $2
  FROM users adm WHERE adm.role='ADMIN' AND EXISTS(SELECT 1 FROM ins) RETURNING 1
)
SELECT email, status FROM ins`;
  params = [name, email, phone, wa, dept, pos];
}
return [{ json: { err, email, sql, params } }];

const built = $('Build Registration').first().json;
const d = $json || {};
let reply;
if (built.err) reply = '\u26a0\ufe0f ' + built.err;
else if (d.email) reply = `\ud83d\udcdd Registration submitted for ${d.email}. Status: ${d.status}. An admin will review it.`;
else reply = `\u26a0\ufe0f ${built.email} is already registered.`;
return [{ json: { reply, status: d.status || null } }];
